import type { ErrorModel } from "@api/generated/model";
import i18n from "@i18n/index";
import { basePath } from "@src/basePath";

/** Shared pieces of the Encore admin API client. The request functions are generated by orval from the server's OpenAPI spec (`src/api/generated/`, see `orval.config.ts`) and go through `orvalFetch`; the resource modules in `src/api/` wrap them in TanStack Query hooks. */
export const API_BASE = `${basePath()}api/v1`;

function isProblem(body: unknown): body is ErrorModel {
  return typeof body === "object" && body !== null && !Array.isArray(body);
}

export class ApiError extends Error {
  readonly status: number;
  readonly body: unknown;
  /** Parsed `application/problem+json` body, when the server sent one. */
  readonly problem: ErrorModel | undefined;

  constructor(message: string, status: number, body?: unknown) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.body = body;
    this.problem = isProblem(body) ? body : undefined;
  }

  /** Validation errors keyed by field name (the last segment of `location`, e.g. `body.password` → `password`). */
  get fieldErrors(): Record<string, string> {
    const out: Record<string, string> = {};
    for (const error of this.problem?.errors ?? []) {
      const key = error.location?.split(".").pop();
      if (key && error.message && !(key in out)) out[key] = error.message;
    }
    return out;
  }
}

/** The message for a failed response: the problem's detail or title, or a generic one. */
export function problemMessage(body: unknown, status: number): string {
  const problem = isProblem(body) ? body : undefined;
  return problem?.detail || problem?.title || i18n.t("error.http", { status });
}

/** A short, human message for any error thrown by the API layer. */
export function errorMessage(error: unknown): string {
  if (error instanceof ApiError) {
    return error.problem?.detail ?? error.problem?.title ?? error.message;
  }
  if (error instanceof Error) return error.message;
  return i18n.t("error.generic");
}

let csrfToken: string | undefined;

/** Set from `GET /auth/state`; sent as `X-CSRF-Token` on every state-changing request. */
export function setCsrfToken(token: string | undefined): void {
  csrfToken = token || undefined;
}

export function getCsrfToken(): string | undefined {
  return csrfToken;
}

type Query = Record<string, string | number | boolean | null | undefined>;

/** An absolute URL under the API base, for links and EventSource (which bypass fetch). */
export function buildUrl(path: string, query?: Query): string {
  let url = `${API_BASE}${path}`;
  if (query) {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined && value !== null && value !== "") params.set(key, String(value));
    }
    const qs = params.toString();
    if (qs) url += `?${qs}`;
  }
  return url;
}
